const tok = [];
let line;
while ((line = readLine()) !== null) for (const t of line.split(/\s+/)) if (t) tok.push(t);
let pos = 0;
const q = Number(tok[pos++]);
const N = 1000000;
const comp = new Uint8Array(N + 1);
comp[0] = comp[1] = 1;
for (let i = 2; i * i <= N; i++) {
  if (!comp[i]) for (let j = i * i; j <= N; j += i) comp[j] = 1;
}
const pi = new Int32Array(N + 1);
for (let i = 1; i <= N; i++) pi[i] = pi[i - 1] + (comp[i] ? 0 : 1);
const out = [];
for (let i = 0; i < q; i++) {
  const l = Number(tok[pos++]);
  const r = Number(tok[pos++]);
  out.push(pi[r] - pi[l - 1]);
}
console.log(out.join('\n'));

