    const int N = 1000000;
    vector<char> comp(N + 1, 0);
    comp[0] = comp[1] = 1;
    for (long long i = 2; i * i <= N; i++)
        if (!comp[i])
            for (long long j = i * i; j <= N; j += i) comp[j] = 1;
    vector<int> pi(N + 1, 0);
    for (int i = 1; i <= N; i++) pi[i] = pi[i - 1] + (comp[i] ? 0 : 1);
    while (q--) {
        int l, r;
        cin >> l >> r;
        cout << pi[r] - pi[l - 1] << "\n";
    }
}

